IF SCHEMA_ID(N'fin') IS NULL EXEC(N'CREATE SCHEMA fin');
GO

IF OBJECT_ID(N'fin.YbPage', N'U') IS NULL
CREATE TABLE fin.YbPage (
    page_code NVARCHAR(12) NOT NULL,
    page_name NVARCHAR(200) NOT NULL,
    page_ref NVARCHAR(40) NOT NULL,
    page_group NVARCHAR(60) NOT NULL,
    line_count INT,
    col_count INT,
    field_count INT,
    source NVARCHAR(40) NOT NULL,
    CONSTRAINT PK_fin_YbPage PRIMARY KEY (page_code)
);
GO

IF OBJECT_ID(N'fin.YbLine', N'U') IS NULL
CREATE TABLE fin.YbLine (
    page_code NVARCHAR(12) NOT NULL,
    line_no NVARCHAR(12) NOT NULL,
    seq INT NOT NULL,
    caption NVARCHAR(400) NOT NULL,
    line_kind NVARCHAR(1) NOT NULL,
    CONSTRAINT PK_fin_YbLine PRIMARY KEY (page_code, line_no)
);
GO

IF OBJECT_ID(N'fin.YbColumn', N'U') IS NULL
CREATE TABLE fin.YbColumn (
