    col_no NVARCHAR(4) NOT NULL,
    data_type NVARCHAR(10) NOT NULL,
    source NVARCHAR(40) NOT NULL,
    concept_id NVARCHAR(60),
    dimensions NVARCHAR(200),
    CONSTRAINT PK_fin_YbField PRIMARY KEY (field_id)
);
GO

